public static long choose(long n, long k) {
    if (k < 0 || k > n) return 0;
    if (k > n / 2) k = n - k;
    if (k == 0) return 1;
    if (k == 1) return n;
    // k <= n/2
    // Will multiply (k) terms, n-k+1 through n-k+k
    // will divide by k terms, 1 through k
    // Note that if we divide after multiplying, it will
    // always be evenly divisible.
    // Proof: when we divide by k, we've multiplied by k consecutive integers,
    // at least one of which will be a multiple of k.
    // Dividing by g = gcd(accum, j) first leaves j/g dividing m, so a step
    // overflows only if its coefficient, which grows with j, does.
    long accum = 1;
    try {
        for (long j = 1; j <= k; j++) {
            long m = n - k + j;
            long g = gcd(accum, j);
            accum = Math.multiplyExact(accum / g, m / (j / g));
        }
    }
    catch (ArithmeticException e) {
        throw overflow();
    }
    return accum;
}

public static long mod(long xi, long yi) {
    long ri = xi % yi;
    if (ri == 0) return 0;

    if (yi > 0) {
        if (xi >= 0) return ri;
        return ri + yi;
    } else {
        if (xi >= 0) return ri + yi;
        return ri;
    }
}

