            if (v < 0) throw Int.divisionByZero();
            return u;
        }
        throw Int.overflow();
    }

    private static BigInteger choose(BigInteger n, BigInteger k) {
        BigInteger nmk = n.subtract(k);
        if (nmk.compareTo(k) < 0) {
